describe('Dynamic Content Updates Announcement for Screen Readers', () => {
  beforeEach(() => {
    cy.visit('/dynamic-content');
  });

  it('should announce dynamic content updates using aria-live regions', () => {
    // Verify initial page loads without announcements
    cy.get('[data-testid="live-region"]').should('be.visible');
    cy.get('[data-testid="content-container"]').should('contain', 'Initial content');

    // Trigger dynamic content update
    cy.get('[data-testid="load-more-button"]').click();

    // Verify new content appears
    cy.get('[data-testid="content-container"]').should('contain', 'More content loaded');

    // Verify aria-live region is used for announcement
    cy.get('[data-testid="live-region"]').should('have.attr', 'aria-live', 'polite');

    // Verify announcement text is present in live region
    cy.get('[data-testid="live-region"]').should('contain', 'Content updated');

    // Verify announcement is visible to screen readers (simulated)
    cy.get('[data-testid="live-region"]').should('be.visible');
  });

  it('should handle multiple dynamic updates and announce each one', () => {
    // First update
    cy.get('[data-testid="load-more-button"]').click();
    cy.get('[data-testid="live-region"]').should('contain', 'Content updated');

    // Second update
    cy.get('[data-testid="load-more-button"]').click();
    cy.get('[data-testid="live-region"]').should('contain', 'More content loaded');

    // Verify content is appended, not replaced
    cy.get('[data-testid="content-container"]').should('have.length.greaterThan', 1);

    // Third update - edge case: empty state
    cy.get('[data-testid="clear-button"]').click();
    cy.get('[data-testid="live-region"]').should('contain', 'Content cleared');

    // Verify content is cleared
    cy.get('[data-testid="content-container"]').should('not.contain', 'More content loaded');

    // Verify aria-live region is still present and functional
    cy.get('[data-testid="live-region"]').should('be.visible');
  });
});
